def predict_grid(test_input):
    rows = []
    for i, row in enumerate(test_input):
        row_list = list(row)
        # Find all 5s in this row
        cols_5 = [c for c, v in enumerate(row_list) if v == 5]

        # Default: background 8
        for c in range(len(row_list)):
            row_list[c] = 8

        # Mark 5s
        for c in cols_5:
            row_list[c] = 5

        # FLUSH applies if there are 2+ 5s in row
        if len(cols_5) >= 2:
            # Left FLUSH: from col 0 to first 5
            for c in range(cols_5[0]):
                row_list[c] = 3

            # Gap fill: between consecutive 5s
            for j in range(len(cols_5) - 1):
                start = cols_5[j] + 1
                end = cols_5[j+1]
                for c in range(start, end):
                    row_list[c] = 3

            # Right FLUSH: after last 5 to end
            for c in range(cols_5[-1] + 1, len(row_list)):
                row_list[c] = 3
        else:
            # Gap fill only
            for j in range(len(cols_5) - 1):
                start = cols_5[j] + 1
                end = cols_5[j+1]
                for c in range(start, end):
                    row_list[c] = 3

        rows.append(row_list)

    return rows

